function sumBy<T>(values: readonly T[], term: (value: T, index: number) => number): number {
  let result = 0;
  for (let i = 0; i < values.length; i++) result += term(values[i], i);
  return result;
}
const sum = (values: readonly number[]): number => sumBy(values, (value) => value);
function crossValidate(data: Data, width: number, lambda: number) {
  const losses: number[] = [];
  const probabilities: number[] = [];
  const foldLosses: number[] = [];
  let errors = 0;
  for (let fold = 0; fold < 5; fold++) {
    const training: number[] = [];
    const validation: number[] = [];
    for (let i = 0; i < data.train.count; i++) (i % 5 === fold ? validation : training).push(i);
    const stats = statistics(
      training.map((i) => data.train.expanded[i]),
      width,
    );
    const vectors = standardize(
      training.map((i) => data.train.expanded[i]),
      stats,
    );
    const targets = training.map((i) => data.train.targets[i]);
    const fitted = newton(vectors, targets, lambda);
    let foldLoss = 0;
    for (const i of validation) {
      const score = logistic.score(fitted.weights, standardizeOne(data.train.expanded[i], stats));
      losses[i] = logistic.loss(score, data.train.targets[i]);
      probabilities[i] = logistic.sigmoid(score);
      foldLoss += losses[i];
      if (Number(probabilities[i] >= data.settings.threshold) !== data.train.targets[i]) errors++;
    }
    foldLosses.push(foldLoss / validation.length);
  }
  return { lambda, foldLosses, loss: sum(losses) / data.train.count, errors, probabilities };
}
function selectLambda(data: Data) {
  const candidates = data.settings.lambdas.map((lambda) =>
    crossValidate(data, data.features.length, lambda),
  );
  let selected = candidates[0];
  for (const candidate of candidates) if (candidate.loss <= selected.loss) selected = candidate;
  const mean = sum(selected.foldLosses) / 5;
  const se =
    Math.sqrt(sumBy(selected.foldLosses, (value) => (value - mean) * (value - mean)) / 4) /
    Math.sqrt(5);
  let oneSE = candidates[0].lambda;
  for (const candidate of candidates) {
    if (candidate.loss <= selected.loss + se) oneSE = candidate.lambda;
  }
  return {
    candidates,
    selected,
    se,
    oneSE,
    confusion: confusion(selected.probabilities, data.train.targets, data.settings.threshold),
    auc: auc(selected.probabilities, data.train.targets),
  };
}
function buildState(data: Data) {
  const validation = selectLambda(data);
  const lambda = validation.selected.lambda;
  const fit = newton(data.train.vectors, data.train.targets, lambda);
  const fitted: NamedFit[] = [
    {
      name: 'gd',
      ...gradientDescent(data.train.vectors, data.train.targets, lambda, ...data.settings.gd),
    },
    {
      name: 'sgd',
      ...stochasticDescent(data.train.vectors, data.train.targets, lambda, ...data.settings.sgd),
    },
    { name: 'newton', ...fit },
  ];
  const models = fitted.map((model) => binaryAnalysis(data, model, lambda));
  const measures = influence(models[2].weights, data.train.vectors, data.train.targets, lambda);
  return {
    validation,
    lambda,
    models,
      `model ${model.name} lambda ${real(state.lambda)}`,
  const coefficients = [`coefficients newton lambda ${real(state.lambda)}`];
    `model ${model.name} lambda ${real(lambda)}`,
  const cv = ['cross_validation folds 5 newton_iterations 10'];
  for (const c of validation.candidates) {
    cv.push(
      `lambda ${real(c.lambda)} fold_loss ${c.foldLosses.map((v) => real(v, 6)).join(' ')} cv_loss ${real(c.loss, 6)} errors ${c.errors}/${n}`,
    );
  }
  cv.push(
    `selected lambda ${real(lambda)} cv_loss ${real(validation.selected.loss, 6)} se ${real(validation.se, 6)} lambda_1se ${real(validation.oneSE)}`,
  );
  const { tp, fp, tn, fn } = validation.confusion;
